import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

import { RATING_SCALE, notchChange, notchCalculator } from '../../src/ratings/notch.mjs';

const SRC_PATH = fileURLToPath(new URL('../../src/ratings/notch.mjs', import.meta.url));

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

test('RATING_SCALE has the 19 ratings, best first, and is frozen', () => {
  assert.deepEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(RATING_SCALE[0], 'AAA');
  assert.equal(RATING_SCALE[18], 'CCC-');
  assert.equal(Object.isFrozen(RATING_SCALE), true);
});

test('RATING_SCALE cannot be mutated (strict mode)', () => {
  assert.throws(() => RATING_SCALE.push('D'), TypeError);
  assert.equal(RATING_SCALE.length, 19);
  assert.throws(() => { RATING_SCALE[0] = 'X'; }, TypeError);
  assert.equal(RATING_SCALE[0], 'AAA');
});

test('notchChange returns index(current) - index(previous)', () => {
  const cases = [
    ['BBB+', 'BB+', 3],
    ['BBB+', 'BBB-', 2],
    ['BBB+', 'BBB', 1],
    ['AA', 'AA', 0],
    ['BB+', 'BBB+', -3],
    ['AAA', 'CCC-', 18],
    ['CCC-', 'AAA', -18],
    ['BBB-', 'BB+', 1],
    ['AAA', 'AAA', 0],
    ['CCC-', 'CCC-', 0],
  ];
  for (const [p, c, n] of cases) {
    assert.equal(notchChange(p, c), n, `${p} -> ${c}`);
  }
});

test('notchCalculator example rows', () => {
  const cases = [
    ['BBB+', 'BB+', { notches: 3, direction: 'downgrade', wl: 2 }],
    ['BBB+', 'BBB-', { notches: 2, direction: 'downgrade', wl: 1 }],
    ['BBB+', 'BBB', { notches: 1, direction: 'downgrade', wl: 0 }],
    ['AAA', 'CCC-', { notches: 18, direction: 'downgrade', wl: 2 }],
    ['A+', 'A-', { notches: 2, direction: 'downgrade', wl: 1 }],
    ['BBB-', 'BB+', { notches: 1, direction: 'downgrade', wl: 0 }],
    ['BB+', 'BBB+', { notches: -3, direction: 'upgrade', wl: 0 }],
    ['BBB', 'BBB+', { notches: -1, direction: 'upgrade', wl: 0 }],
    ['CCC-', 'AAA', { notches: -18, direction: 'upgrade', wl: 0 }],
    ['AA', 'AA', { notches: 0, direction: 'unchanged', wl: 0 }],
    ['AAA', 'AAA', { notches: 0, direction: 'unchanged', wl: 0 }],
    ['CCC-', 'CCC-', { notches: 0, direction: 'unchanged', wl: 0 }],
    ['\tbbb+\n', 'bbb-', { notches: 2, direction: 'downgrade', wl: 1 }],
  ];
  for (const [p, c, expected] of cases) {
    assert.deepStrictEqual(notchCalculator(p, c), expected, `${p} -> ${c}`);
  }
});

test('all 361 ordered pairs are consistent, with the expected control totals', () => {
  const totals = { downgrade: 0, upgrade: 0, unchanged: 0, wl0: 0, wl1: 0, wl2: 0 };
  let pairs = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      pairs += 1;
      const n = notchChange(p, c);
      assert.ok(Number.isInteger(n) && n >= -18 && n <= 18);
      const r = notchCalculator(p, c);
      assert.equal(r.notches, n);
      const direction = n > 0 ? 'downgrade' : n < 0 ? 'upgrade' : 'unchanged';
      assert.equal(r.direction, direction);
      const wl = n <= 1 ? 0 : n === 2 ? 1 : 2;
      assert.equal(r.wl, wl);
      assert.deepEqual(Object.keys(r).sort(), ['direction', 'notches', 'wl']);
      totals[direction] += 1;
      totals[`wl${wl}`] += 1;
    }
  }
  assert.equal(pairs, 361);
  assert.deepEqual(totals, {
    downgrade: 171, upgrade: 171, unchanged: 19, wl0: 208, wl1: 17, wl2: 136,
  });
});

test('input is trimmed and upper-cased', () => {
  assert.equal(notchChange(' bbb+ ', 'Bb+'), 3);
  assert.equal(notchChange('aaa', 'ccc-'), 18);
  assert.equal(notchChange(' BBB ', 'BBB'), 0);
  assert.equal(notchChange(' BBB ', 'BBB'), 0);
  assert.deepStrictEqual(notchCalculator('\tbbb+\n', 'bbb-'), {
    notches: 2, direction: 'downgrade', wl: 1,
  });
});

const INVALID = [
  '', '   ', 'BBB +', 'B BB', 'BBB−', 'BBB–', 'CC', 'C', 'D', 'SD', 'RD', 'NR',
  'Baa1', 'AAA+', null, undefined, 7, true, {}, ['BBB'], new String('BBB'),
  Symbol('x'), Object.create(null), 10n,
];

test('invalid input throws RangeError (never TypeError) in either position', () => {
  for (const v of INVALID) {
    assert.throws(() => notchChange(v, 'BBB'), RangeError);
    assert.throws(() => notchChange('BBB', v), RangeError);
    assert.throws(() => notchCalculator(v, 'BBB'), RangeError);
    assert.throws(() => notchCalculator('BBB', v), RangeError);
  }
});

test('a missing argument reports current', () => {
  assert.throws(() => notchChange('BBB'), (e) => e instanceof RangeError && /current/.test(e.message));
  assert.throws(() => notchCalculator('BBB'), (e) => e instanceof RangeError && /current/.test(e.message));
});

test('error message names the argument and echoes the value', () => {
  for (const fn of [notchChange, notchCalculator]) {
    assert.throws(
      () => fn('XX', 'YY'),
      (e) => e instanceof RangeError && e.message.includes('previous') && e.message.includes('XX'),
