    assert.throws(
      () => fn('BBB', 'YY'),
      (e) => e instanceof RangeError && e.message.includes('current') && e.message.includes('YY'),
    );
  }
});

test('both invalid names previous, not current', () => {
  assert.throws(() => notchChange('XX', 'YY'), (e) => !e.message.includes('current'));
});

test('same arguments give equal results, each a fresh object; no state kept', () => {
  const a = notchCalculator('BBB+', 'BB+');
  const b = notchCalculator('BBB+', 'BB+');
  assert.deepStrictEqual(a, b);
  assert.notEqual(a, b);
