  a.extra = true;
  assert.deepStrictEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
  assert.equal(notchChange('BBB+', 'BB+'), notchChange('BBB+', 'BB+'));
});

test('module is silent in a child process, including a caught RangeError', () => {
  const code = `
