// T-01 QA: integration tests for src/ratings/notch.mjs through its public exports.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import {
  RATING_SCALE,
  notchChange,
  notchCalculator,
} from '../../../src/ratings/notch.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../../..');
const notchPath = path.join(root, 'src/ratings/notch.mjs');

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

const INVALID = [
  '', '   ', 'BBB +', 'BBB−', 'CC', 'C', 'D', 'SD', 'RD', 'NR', 'Baa1', 'AAA+',
  null, undefined, 7, {}, ['BBB'],
];

test('AC-1: RATING_SCALE has the 19 ratings in order, is frozen', () => {
  assert.deepStrictEqual([...RATING_SCALE], EXPECTED_SCALE);
  assert.deepEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(RATING_SCALE[0], 'AAA');
  assert.equal(RATING_SCALE[18], 'CCC-');
  assert.equal(Object.isFrozen(RATING_SCALE), true);
});

test('AC-1: in strict mode push and index assignment throw TypeError and leave the scale intact', () => {
  assert.throws(() => RATING_SCALE.push('D'), TypeError);
  assert.equal(RATING_SCALE.length, 19);
  assert.throws(() => { RATING_SCALE[0] = 'X'; }, TypeError);
  assert.equal(RATING_SCALE[0], 'AAA');
  assert.deepStrictEqual([...RATING_SCALE], EXPECTED_SCALE);
});

test('AC-2: notchChange = index(current) - index(previous) for the spec data', () => {
  const cases = [
    ['BBB+', 'BB+', 3], ['BBB+', 'BBB-', 2], ['BBB+', 'BBB', 1], ['AA', 'AA', 0],
    ['BB+', 'BBB+', -3], ['AAA', 'CCC-', 18], ['CCC-', 'AAA', -18],
  ];
  for (const [p, c, n] of cases) {
    assert.equal(notchChange(p, c), n, `${p} -> ${c}`);
  }
});

test('AC-2: notchChange is an integer in -18..18, sign: positive downgrade, negative upgrade, 0 unchanged', () => {
  for (const [i, p] of RATING_SCALE.entries()) {
    for (const [j, c] of RATING_SCALE.entries()) {
      const n = notchChange(p, c);
      assert.ok(Number.isInteger(n), `${p}->${c} integer`);
      assert.ok(n >= -18 && n <= 18, `${p}->${c} range`);
      assert.equal(n, j - i);
      assert.equal(Math.sign(n), Math.sign(j - i));
    }
  }
});

test('AC-3: notchCalculator downgrade examples (BBB+ -> BB+ is 3 notches, WL 2)', () => {
  assert.deepStrictEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
  assert.deepStrictEqual(notchCalculator('BBB+', 'BBB-'), { notches: 2, direction: 'downgrade', wl: 1 });
  assert.deepStrictEqual(notchCalculator('BBB+', 'BBB'), { notches: 1, direction: 'downgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('AAA', 'CCC-'), { notches: 18, direction: 'downgrade', wl: 2 });
  assert.deepStrictEqual(notchCalculator('A+', 'A-'), { notches: 2, direction: 'downgrade', wl: 1 });
  assert.deepStrictEqual(notchCalculator('BBB-', 'BB+'), { notches: 1, direction: 'downgrade', wl: 0 });
});

test('AC-3: the wrong POC example (2 notches / WL 1 for BBB+ -> BB+) does not hold', () => {
  const r = notchCalculator('BBB+', 'BB+');
  assert.notEqual(r.notches, 2);
  assert.notEqual(r.wl, 1);
  assert.notEqual(notchChange('BBB+', 'BB+'), 2);
});

test('AC-4: upgrades and unchanged give negative/zero notches and WL 0', () => {
  assert.deepStrictEqual(notchCalculator('BB+', 'BBB+'), { notches: -3, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('BBB', 'BBB+'), { notches: -1, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('CCC-', 'AAA'), { notches: -18, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('AA', 'AA'), { notches: 0, direction: 'unchanged', wl: 0 });
});

test('AC-4: scale ends are valid in both positions and unchanged at the ends is WL 0', () => {
  assert.deepStrictEqual(notchCalculator('AAA', 'AAA'), { notches: 0, direction: 'unchanged', wl: 0 });
  assert.deepStrictEqual(notchCalculator('CCC-', 'CCC-'), { notches: 0, direction: 'unchanged', wl: 0 });
});

test('AC-5: all 361 ordered pairs are consistent, with control totals', () => {
  const tot = { downgrade: 0, upgrade: 0, unchanged: 0, wl0: 0, wl1: 0, wl2: 0 };
  let pairs = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      pairs++;
      const r = notchCalculator(p, c);
      assert.equal(r.notches, notchChange(p, c), `${p}->${c} notches`);
      const dir = r.notches > 0 ? 'downgrade' : r.notches < 0 ? 'upgrade' : 'unchanged';
      assert.equal(r.direction, dir, `${p}->${c} direction`);
      const wl = r.notches <= 1 ? 0 : r.notches === 2 ? 1 : 2;
      assert.equal(r.wl, wl, `${p}->${c} wl`);
      assert.deepStrictEqual(Object.keys(r).sort(), ['direction', 'notches', 'wl']);
      tot[r.direction]++;
      tot[`wl${r.wl}`]++;
    }
  }
  assert.equal(pairs, 361);
  assert.deepStrictEqual(tot, { downgrade: 171, upgrade: 171, unchanged: 19, wl0: 208, wl1: 17, wl2: 136 });
});

test('AC-8: input is trimmed and case-insensitive', () => {
  assert.equal(notchChange(' bbb+ ', 'Bb+'), 3);
  assert.equal(notchChange('aaa', 'ccc-'), 18);
  assert.deepStrictEqual(notchCalculator('\tbbb+\n', 'bbb-'), { notches: 2, direction: 'downgrade', wl: 1 });
});

test('AC-8: NBSP is stripped by trim, so " BBB " is valid', () => {
  assert.equal(notchChange(' BBB ', 'BBB'), 0);
  assert.equal(notchChange(' BBB ', 'BBB'), 0);
});

test('AC-9: every invalid value throws RangeError (never TypeError) in either position, in both functions', () => {
  for (const v of INVALID) {
    const label = (() => { try { return JSON.stringify(v) ?? String(v); } catch { return '?'; } })();
    for (const [name, fn] of [
      ['notchChange(V,BBB)', () => notchChange(v, 'BBB')],
      ['notchChange(BBB,V)', () => notchChange('BBB', v)],
      ['notchCalculator(V,BBB)', () => notchCalculator(v, 'BBB')],
      ['notchCalculator(BBB,V)', () => notchCalculator('BBB', v)],
    ]) {
      assert.throws(fn, RangeError, `${name} with ${label}`);
    }
  }
});

test('AC-9: edge inputs (boxed strings, Symbol, null-prototype object, booleans, missing arg, inner whitespace, dashes)', () => {
  const extra = [
    new String('BBB'), Symbol('x'), Object.create(null), true, false, 0, NaN,
    'B BB', 'BBB–', 'BBB−', 'AAA+', 'bbb +',
  ];
  for (const v of extra) {
    assert.throws(() => notchChange(v, 'BBB'), RangeError);
    assert.throws(() => notchChange('BBB', v), RangeError);
    assert.throws(() => notchCalculator(v, 'BBB'), RangeError);
    assert.throws(() => notchCalculator('BBB', v), RangeError);
  }
  assert.throws(() => notchChange('BBB'), RangeError);
  assert.throws(() => notchCalculator('BBB'), RangeError);
  assert.throws(() => notchChange(), RangeError);
  assert.throws(() => notchChange('BBB', ['BBB']), RangeError);
});

test('AC-10: error message names the offending argument and echoes its value', () => {
  assert.throws(() => notchChange('XX', 'YY'), (e) => {
    assert.ok(e instanceof RangeError);
    assert.match(e.message, /previous/);
    assert.match(e.message, /XX/);
    return true;
  });
  assert.throws(() => notchChange('BBB', 'YY'), (e) => {
    assert.ok(e instanceof RangeError);
    assert.match(e.message, /current/);
    assert.match(e.message, /YY/);
    return true;
  });
  assert.throws(() => notchCalculator('XX', 'YY'), (e) => {
    assert.ok(e instanceof RangeError && /previous/.test(e.message) && /XX/.test(e.message));
    return true;
  });
  assert.throws(() => notchCalculator('BBB', 'YY'), (e) => {
    assert.ok(e instanceof RangeError && /current/.test(e.message) && /YY/.test(e.message));
    return true;
  });
});

test('AC-10: missing second argument reports current; both invalid reports previous', () => {
  assert.throws(() => notchChange('BBB'), (e) => e instanceof RangeError && /current/.test(e.message));
  assert.throws(() => notchChange('XX', 'YY'), (e) => !/current/.test(e.message));
});

test('AC-11: same arguments give equal results, each a fresh object, no state kept', () => {
  const a = notchCalculator('BBB+', 'BB+');
  const b = notchCalculator('BBB+', 'BB+');
  assert.deepStrictEqual(a, b);
  assert.notEqual(a, b);
  a.wl = 9;
  a.extra = true;
  assert.deepStrictEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
  assert.equal(notchChange('BBB+', 'BB+'), notchChange('BBB+', 'BB+'));
  // an invalid call in between does not influence later results
  assert.throws(() => notchChange('ZZ', 'BBB'), RangeError);
  assert.deepStrictEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
});

test('AC-11: child process using the module (incl. a caught RangeError) prints nothing and exits 0', () => {
  const code = `
    import { RATING_SCALE, notchChange, notchCalculator } from ${JSON.stringify(notchPath)};
    notchChange('BBB+','BB+');
    notchCalculator('AAA','CCC-');
    void RATING_SCALE.length;
    try { notchChange('XX','YY'); } catch (e) { if (!(e instanceof RangeError)) process.exit(3); }
    try { notchCalculator(Symbol('s'), 'BBB'); } catch (e) { if (!(e instanceof RangeError)) process.exit(4); }
