  assert.equal(r.stderr, '');
});

test('AC-11: source has no import/require and no console/stdout/stderr usage', () => {
  const src = readFileSync(notchPath, 'utf8')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/(^|[^:])\/\/.*$/gm, '$1');
  assert.doesNotMatch(src, /^\s*import\b/m);
  assert.doesNotMatch(src, /\bimport\s*\(/);
  assert.doesNotMatch(src, /\brequire\s*\(/);
  assert.doesNotMatch(src, /console\./);
  assert.doesNotMatch(src, /process\.stdout/);
  assert.doesNotMatch(src, /process\.stderr/);
});

test('AC-12: contract files exist as plain ESM, unit tests pass, package.json clean and unchanged', () => {
  assert.ok(existsSync(notchPath), 'src/ratings/notch.mjs exists');
  const unit = path.join(root, 'test/ratings/notch.test.mjs');
  assert.ok(existsSync(unit), 'test/ratings/notch.test.mjs exists');

  const src = readFileSync(notchPath, 'utf8');
  assert.match(src, /^export\s/m);
  assert.doesNotMatch(src, /module\.exports|\bexports\./);

  // run the dev's unit tests as a child (not the whole suite: that would recurse into this file)
  const r = spawnSync(process.execPath, ['--test', unit], { encoding: 'utf8', cwd: root });
  assert.equal(r.status, 0, r.stdout + r.stderr);
  assert.match(r.stdout, /# fail 0/);

  const pkg = JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8'));
  assert.equal('dependencies' in pkg, false);
  assert.equal('devDependencies' in pkg, false);

  const diff = spawnSync('git', ['diff', '--quiet', 'main', '--', 'package.json'], { cwd: root });
  assert.equal(diff.status, 0, 'package.json differs from main');
});
