/**
 * Notch calculator (REQ-06-02): turns a previous and a current rating into a
 * notch change, a direction and a Watchlist level (WL, 0-4, higher is worse).
 * Pure functions: no I/O, no output, no state.
 */

/**
 * The 19 supported long-term ratings, best first. Index 0 is "AAA", index 18
 * is "CCC-". Frozen: any attempt to modify it throws a TypeError in strict mode.
 * @type {readonly string[]}
 */
export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

/**
 * Best-effort text for an invalid value inside an error message. Never throws
 * (Symbols, null-prototype objects and hostile objects/proxies can make String()
 * or toString throw).
 * @param {unknown} value
 * @returns {string}
 */
function describe(value) {
  try {
    return typeof value === 'string' ? JSON.stringify(value) : String(value);
  } catch {
    try {
      return Object.prototype.toString.call(value);
    } catch {
      return '[unprintable value]';
    }
  }
}

/**
 * Validate one rating argument and return its index on RATING_SCALE.
 * Normalisation: trim(), then toUpperCase(). Internal whitespace is kept, so
 * "BBB +" is invalid. Non-strings (including String objects) are invalid.
 * @param {unknown} value
 * @param {'previous'|'current'} name
 * @returns {number}
 * @throws {RangeError}
 */
function indexOfRating(value, name) {
  const index = typeof value === 'string'
    ? RATING_SCALE.indexOf(value.trim().toUpperCase())
    : -1;
  if (index === -1) {
    throw new RangeError(
      `Invalid ${name} rating: ${describe(value)} is not one of ${RATING_SCALE.join(', ')}`,
    );
  }
  return index;
}

/**
 * Number of notches between two ratings: index(current) - index(previous).
 * Sign convention: positive = downgrade, negative = upgrade, 0 = unchanged.
 * Result is an integer from -18 to +18.
 * @param {string} previous rating before the change (e.g. "BBB+"); trimmed and upper-cased
 * @param {string} current rating after the change (e.g. "BB+"); trimmed and upper-cased
 * @returns {number} signed notch change
 * @throws {RangeError} if an argument is not one of the 19 ratings; `previous`
 *   is checked first, and the message names the offending argument and its value
 */
export function notchChange(previous, current) {
  const from = indexOfRating(previous, 'previous');
  const to = indexOfRating(current, 'current');
  return to - from;
}

/**
 * Notch change, direction and resulting WL for a rating move.
 *
 * `wl` uses the Indicator 13 thresholds: notches <= 1 -> 0 (all upgrades and
 * unchanged included), notches === 2 -> 1, notches >= 3 -> 2. This differs on
 * purpose from Indicator 12 (countryRatingChangeWl), which gives WL 1 for a
 * 1-notch downgrade (C6).
 *
 * Sign convention: `notches` is positive for a downgrade, negative for an
 * upgrade, 0 when unchanged. Example: ("BBB+", "BB+") is 3 notches, WL 2.
 *
 * @param {string} previous rating before the change; trimmed and upper-cased
 * @param {string} current rating after the change; trimmed and upper-cased
 * @returns {{notches: number, direction: 'downgrade'|'upgrade'|'unchanged', wl: number}}
 *   a new object on every call
 * @throws {RangeError} if an argument is not one of the 19 ratings (see notchChange)
 */
export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
  return { notches, direction, wl };
}
// T-01 QA: integration tests for src/ratings/notch.mjs through its public exports.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import {
  RATING_SCALE,
  notchChange,
  notchCalculator,
} from '../../../src/ratings/notch.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../../..');
const notchPath = path.join(root, 'src/ratings/notch.mjs');

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

const INVALID = [
  '', '   ', 'BBB +', 'BBB−', 'CC', 'C', 'D', 'SD', 'RD', 'NR', 'Baa1', 'AAA+',
  null, undefined, 7, {}, ['BBB'],
];

test('AC-1: RATING_SCALE has the 19 ratings in order, is frozen', () => {
  assert.deepStrictEqual([...RATING_SCALE], EXPECTED_SCALE);
  assert.deepEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(RATING_SCALE[0], 'AAA');
  assert.equal(RATING_SCALE[18], 'CCC-');
  assert.equal(Object.isFrozen(RATING_SCALE), true);
});

test('AC-1: in strict mode push and index assignment throw TypeError and leave the scale intact', () => {
  assert.throws(() => RATING_SCALE.push('D'), TypeError);
  assert.equal(RATING_SCALE.length, 19);
  assert.throws(() => { RATING_SCALE[0] = 'X'; }, TypeError);
  assert.equal(RATING_SCALE[0], 'AAA');
  assert.deepStrictEqual([...RATING_SCALE], EXPECTED_SCALE);
});

test('AC-2: notchChange = index(current) - index(previous) for the spec data', () => {
  const cases = [
    ['BBB+', 'BB+', 3], ['BBB+', 'BBB-', 2], ['BBB+', 'BBB', 1], ['AA', 'AA', 0],
    ['BB+', 'BBB+', -3], ['AAA', 'CCC-', 18], ['CCC-', 'AAA', -18],
  ];
  for (const [p, c, n] of cases) {
    assert.equal(notchChange(p, c), n, `${p} -> ${c}`);
  }
});

test('AC-2: notchChange is an integer in -18..18, sign: positive downgrade, negative upgrade, 0 unchanged', () => {
  for (const [i, p] of RATING_SCALE.entries()) {
    for (const [j, c] of RATING_SCALE.entries()) {
      const n = notchChange(p, c);
      assert.ok(Number.isInteger(n), `${p}->${c} integer`);
      assert.ok(n >= -18 && n <= 18, `${p}->${c} range`);
      assert.equal(n, j - i);
      assert.equal(Math.sign(n), Math.sign(j - i));
    }
  }
});

test('AC-3: notchCalculator downgrade examples (BBB+ -> BB+ is 3 notches, WL 2)', () => {
  assert.deepStrictEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
  assert.deepStrictEqual(notchCalculator('BBB+', 'BBB-'), { notches: 2, direction: 'downgrade', wl: 1 });
  assert.deepStrictEqual(notchCalculator('BBB+', 'BBB'), { notches: 1, direction: 'downgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('AAA', 'CCC-'), { notches: 18, direction: 'downgrade', wl: 2 });
  assert.deepStrictEqual(notchCalculator('A+', 'A-'), { notches: 2, direction: 'downgrade', wl: 1 });
  assert.deepStrictEqual(notchCalculator('BBB-', 'BB+'), { notches: 1, direction: 'downgrade', wl: 0 });
});

test('AC-3: the wrong POC example (2 notches / WL 1 for BBB+ -> BB+) does not hold', () => {
  const r = notchCalculator('BBB+', 'BB+');
  assert.notEqual(r.notches, 2);
  assert.notEqual(r.wl, 1);
  assert.notEqual(notchChange('BBB+', 'BB+'), 2);
});

test('AC-4: upgrades and unchanged give negative/zero notches and WL 0', () => {
  assert.deepStrictEqual(notchCalculator('BB+', 'BBB+'), { notches: -3, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('BBB', 'BBB+'), { notches: -1, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('CCC-', 'AAA'), { notches: -18, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('AA', 'AA'), { notches: 0, direction: 'unchanged', wl: 0 });
});

test('AC-4: scale ends are valid in both positions and unchanged at the ends is WL 0', () => {
  assert.deepStrictEqual(notchCalculator('AAA', 'AAA'), { notches: 0, direction: 'unchanged', wl: 0 });
  assert.deepStrictEqual(notchCalculator('CCC-', 'CCC-'), { notches: 0, direction: 'unchanged', wl: 0 });
});

test('AC-5: all 361 ordered pairs are consistent, with control totals', () => {
  const tot = { downgrade: 0, upgrade: 0, unchanged: 0, wl0: 0, wl1: 0, wl2: 0 };
  let pairs = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      pairs++;
      const r = notchCalculator(p, c);
      assert.equal(r.notches, notchChange(p, c), `${p}->${c} notches`);
      const dir = r.notches > 0 ? 'downgrade' : r.notches < 0 ? 'upgrade' : 'unchanged';
      assert.equal(r.direction, dir, `${p}->${c} direction`);
      const wl = r.notches <= 1 ? 0 : r.notches === 2 ? 1 : 2;
