+    ['CCC-', 'AAA', { notches: -18, direction: 'upgrade', wl: 0 }],
+    ['AA', 'AA', { notches: 0, direction: 'unchanged', wl: 0 }],
+    ['AAA', 'AAA', { notches: 0, direction: 'unchanged', wl: 0 }],
+    ['CCC-', 'CCC-', { notches: 0, direction: 'unchanged', wl: 0 }],
