/**
 * Notch calculator (REQ-06-02): turns a previous and a current rating into a
 * notch change, a direction and a Watchlist level (WL, 0-4, higher is worse).
 * Pure functions: no I/O, no output, no state.
 */

/**
 * The 19 supported long-term ratings, best first. Index 0 is "AAA", index 18
 * is "CCC-". Frozen: any attempt to modify it throws a TypeError in strict mode.
 * @type {readonly string[]}
 */
export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

/**
 * Best-effort text for an invalid value inside an error message. Never throws
 * (Symbols, null-prototype objects and hostile objects/proxies can make String()
 * or toString throw).
 * @param {unknown} value
 * @returns {string}
 */
function describe(value) {
  try {
    return typeof value === 'string' ? JSON.stringify(value) : String(value);
  } catch {
    try {
      return Object.prototype.toString.call(value);
    } catch {
      return '[unprintable value]';
    }
  }
}

/**
 * Validate one rating argument and return its index on RATING_SCALE.
 * Normalisation: trim(), then toUpperCase(). Internal whitespace is kept, so
 * "BBB +" is invalid. Non-strings (including String objects) are invalid.
 * @param {unknown} value
 * @param {'previous'|'current'} name
 * @returns {number}
 * @throws {RangeError}
 */
function indexOfRating(value, name) {
  const index = typeof value === 'string'
    ? RATING_SCALE.indexOf(value.trim().toUpperCase())
    : -1;
  if (index === -1) {
    throw new RangeError(
      `Invalid ${name} rating: ${describe(value)} is not one of ${RATING_SCALE.join(', ')}`,
    );
  }
  return index;
}

/**
 * Number of notches between two ratings: index(current) - index(previous).
 * Sign convention: positive = downgrade, negative = upgrade, 0 = unchanged.
 * Result is an integer from -18 to +18.
 * @param {string} previous rating before the change (e.g. "BBB+"); trimmed and upper-cased
 * @param {string} current rating after the change (e.g. "BB+"); trimmed and upper-cased
 * @returns {number} signed notch change
 * @throws {RangeError} if an argument is not one of the 19 ratings; `previous`
 *   is checked first, and the message names the offending argument and its value
 */
export function notchChange(previous, current) {
  const from = indexOfRating(previous, 'previous');
  const to = indexOfRating(current, 'current');
  return to - from;
}

/**
 * Notch change, direction and resulting WL for a rating move.
 *
 * `wl` uses the Indicator 13 thresholds: notches <= 1 -> 0 (all upgrades and
 * unchanged included), notches === 2 -> 1, notches >= 3 -> 2. This differs on
 * purpose from Indicator 12 (countryRatingChangeWl), which gives WL 1 for a
 * 1-notch downgrade (C6).
 *
 * Sign convention: `notches` is positive for a downgrade, negative for an
 * upgrade, 0 when unchanged. Example: ("BBB+", "BB+") is 3 notches, WL 2.
 *
 * @param {string} previous rating before the change; trimmed and upper-cased
 * @param {string} current rating after the change; trimmed and upper-cased
 * @returns {{notches: number, direction: 'downgrade'|'upgrade'|'unchanged', wl: number}}
 *   a new object on every call
 * @throws {RangeError} if an argument is not one of the 19 ratings (see notchChange)
 */
export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
  return { notches, direction, wl };
}

