+/**
+ * Indicator 12 (REQ-03-12): country rating change. Pure function: no I/O,
+ * no output, no state.
+ */
+import { notchChange } from '../ratings/notch.mjs';
+
+/**
+ * Watchlist level (WL, 0-4, higher is worse) for a change in a country's
+ * rating, using the Indicator 12 thresholds on n = notchChange(previous, current):
+ * n <= 0 -> 0 (an upgrade or unchanged rating never raises the WL),
+ * n === 1 -> 1, n >= 2 -> 2.
+ *
+ * These thresholds differ on purpose from notchCalculator (Indicator 13:
+ * n <= 1 -> 0, n === 2 -> 1, n >= 3 -> 2). Example: ("BBB+", "BBB") is a
+ * 1-notch downgrade, so this function returns 1 while notchCalculator
+ * returns wl 0.
+ *
+ * Normalisation and validation are done by notchChange.
+ *
+ * @param {string} previous the country's rating before the change
+ * @param {string} current the country's rating after the change
+ * @returns {0|1|2}
+ * @throws {RangeError} if an argument is not one of the supported ratings; the
+ *   error comes unchanged from notchChange, `previous` is checked first and the
+ *   message names the offending argument and its value
+ */
+export function countryRatingChangeWl(previous, current) {
+  const n = notchChange(previous, current);
+  if (n <= 0) return 0;
+  return n === 1 ? 1 : 2;
+}
